#!/usr/bin/env python3
"""
Cerebral-Wikia Native MCP Server
Antropofagia Tecnológica: devorou agent-memory-mcp → MCP nativo OpenCode
"""

import asyncio
import json
import sys
from pathlib import Path
from typing import Any, Dict, List, Optional

# Add memory_engine to path
sys.path.insert(0, str(Path(__file__).parent))

from memory_engine import CerebralMemoryEngine, MemoryEntry, Entity, Concept


class CerebralMCPServer:
    """MCP Server for Cerebral-Wikia native memory engine"""

    def __init__(self, brain_path: str = "/mnt/dados/cerebro com IA"):
        self.engine = CerebralMemoryEngine(Path(brain_path) / "cerebral.db")
        self.tools = {
            "memory_search": self._search,
            "memory_write": self._write,
            "memory_read": self._read,
            "memory_stats": self._stats,
            "memory_ingest": self._ingest,
            "memory_entities": self._entities,
            "memory_concepts": self._concepts,
            "memory_relations": self._relations,
        }

    async def handle_request(self, request: Dict[str, Any]) -> Dict[str, Any]:
        """Handle MCP request"""
        method = request.get("method")
        params = request.get("params", {})
        request_id = request.get("id")

        try:
            if method == "tools/list":
                result = self._list_tools()
            elif method == "tools/call":
                tool_name = params.get("name")
                arguments = params.get("arguments", {})
                result = await self._call_tool(tool_name, arguments)
            else:
                result = {"error": f"Unknown method: {method}"}

            return {"jsonrpc": "2.0", "id": request_id, "result": result}
        except Exception as e:
            return {"jsonrpc": "2.0", "id": request_id, "error": {"code": -1, "message": str(e)}}

    def _list_tools(self) -> Dict[str, Any]:
        """List available tools"""
        return {
            "tools": [
                {
                    "name": "memory_search",
                    "description": "Search memories by query, type, or tags",
                    "inputSchema": {
                        "type": "object",
