        re.compile(r'&&'),
        re.compile(r'\|\|'),
        re.compile(r'`'),
        re.compile(r'\$\('),
        re.compile(r'\$\{'),
        re.compile(r'>\s*/dev'),
        re.compile(r'<\s*/dev'),
        re.compile(r'\bnc\b'),
        re.compile(r'\bncat\b'),
        re.compile(r'\bcurl\b'),
        re.compile(r'\bwget\b'),
        re.compile(r'\bpython3?\b'),
        re.compile(r'\bbash\b'),
        re.compile(r'\bsh\b'),
        re.compile(r'\bchmod\b'),
        re.compile(r'\bchown\b'),
        re.compile(r'\bmv\b'),
        re.compile(r'\bcp\b'),
        re.compile(r'\brm\b'),
        re.compile(r'\bmkdir\b'),
        re.compile(r'\bexport\b'),
        re.compile(r'\bsource\b'),
    ]

    @classmethod
    def validate(cls, command: str) -> tuple[bool, Optional[str]]:
        cleaned = command.strip()
        if not cleaned:
            return False, "Empty command"
        for pattern in cls.FORBIDDEN_PATTERNS:
            if pattern.search(cleaned):
                return False, f"Potential shell injection pattern matched: {pattern.pattern}"
