class SystemHealthChecker:
    """Lightweight health checks using /proc when available"""

    @staticmethod
    def _read_proc_cpu() -> Optional[float]:
        try:
            with open("/proc/stat") as f:
                for line in f:
                    if line.startswith("cpu "):
                        parts = line.split()
                        idle = int(parts[4])
                        total = sum(map(int, parts[1:]))
                        return idle / total if total else None
        except Exception:
            pass
        return None

    @staticmethod
    def _read_proc_mem() -> Optional[float]:
        try:
            with open("/proc/meminfo") as f:
                lines = f.read().splitlines()
            values = {line.split(":")[0].strip(): int(line.split(":")[1].strip().split()[0]) for line in lines}
            mem_total = values.get("MemTotal")
            mem_free = values.get("MemAvailable") or values.get("MemFree")
            if mem_total and mem_free:
                return mem_free / mem_total
        except Exception:
            pass
        return None

    @classmethod
    def is_healthy(cls, max_cpu: float = 90.0, max_memory: float = 90.0) -> tuple[bool, Dict[str, Any]]:
        cpu_usage = 100.0
        mem_usage = 100.0
        cpu_ratio = cls._read_proc_cpu()
        mem_ratio = cls._read_proc_mem()
        if cpu_ratio is not None:
            cpu_usage = round((1.0 - cpu_ratio) * 100, 2)
        if mem_ratio is not None:
            mem_usage = round((1.0 - mem_ratio) * 100, 2)
        healthy = cpu_usage < max_cpu and mem_usage < max_memory
        return healthy, {"cpu_usage": cpu_usage, "memory_usage": mem_usage}


