async def execute_plan(self, waves: List[List[AtlasTask]]) -> Dict[str, AtlasTask]:
    """Execute all waves sequentially, tasks within wave in parallel"""
    all_results: Dict[str, AtlasTask] = {}
    self.logger.info("execution.started", waves=len(waves), max_parallel=self.max_parallel)

    for wave_num, wave_task_ids in enumerate(waves):
        wave_tasks = [
            self.tasks[tid]
            for tid in wave_task_ids
            if tid in self.tasks and self.tasks[tid].status == TaskStatus.PENDING
        ]

        for task in wave_tasks:
            task.wave = wave_num

        if not wave_tasks:
            continue

        if wave_num > 0 and self.health_check_between_waves:
            healthy, metrics = SystemHealthChecker.is_healthy(self.max_cpu_percent, self.max_memory_percent)
            self.logger.info("wave.health_check", wave=wave_num, healthy=healthy, **metrics)
            if not healthy:
                self.logger.warning("wave.health_check.failed", wave=wave_num, **metrics)
                for task in wave_tasks:
                    task.status = TaskStatus.SKIPPED
                    task.error = "System health check failed before wave execution"
                    task.completed_at = time.time()
                    all_results[task.id] = task
                skipped = self._skip_dependents({t.id for t in wave_tasks}, wave_num, waves)
                all_results.update(skipped)
                continue

        wave_results = await self.execute_wave(wave_tasks)
        self.wave_results.append({t.id: t for t in wave_results})
        self.logger.info("wave.completed", wave=wave_num, tasks=len(wave_results))

        failed = [t for t in wave_results if t.status == TaskStatus.FAILED]
        if failed:
            for task in wave_results:
                all_results[task.id] = task
            failed_ids = {t.id for t in failed}
            skipped = self._skip_dependents(failed_ids, wave_num, waves)
            all_results.update(skipped)
        else:
            for task in wave_results:
                all_results[task.id] = task

    self.results = all_results
    self.logger.info("execution.finished", **self.get_summary())
    return all_results

