class StructuredLogger:
    """JSON-line logger for production observability"""

    def __init__(self, log_path: Optional[str] = None, level: int = logging.INFO, execution_uuid: Optional[str] = None):
        self.execution_uuid = execution_uuid
        self.logger = logging.getLogger("atlas_parallel")
        self.logger.setLevel(level)
        self.logger.propagate = False
        if not self.logger.handlers:
            handler = logging.FileHandler(log_path) if log_path else logging.StreamHandler()
            handler.setFormatter(logging.Formatter("%(message)s"))
            self.logger.addHandler(handler)

    def _log(self, level: int, event: str, **fields):
        payload = {"timestamp": time.time(), "level": logging.getLevelName(level), "event": event}
        if self.execution_uuid:
            payload["execution_uuid"] = self.execution_uuid
        payload.update(fields)
        self.logger.log(level, json.dumps(payload, ensure_ascii=False))

    def debug(self, event: str, **fields):
        self._log(logging.DEBUG, event, **fields)

    def info(self, event: str, **fields):
        self._log(logging.INFO, event, **fields)

    def warning(self, event: str, **fields):
        self._log(logging.WARNING, event, **fields)

    def error(self, event: str, **fields):
        self._log(logging.ERROR, event, **fields)

