class WaveStrategy(ExecutionStrategy):
    def __init__(self, executor: WaveExecutor):
        self.executor = executor

    async def execute(self, tasks: List[AtlasTask]) -> Dict[str, Any]:
        planner = WavePlanner()
        for task in tasks:
            planner.add_task(task)
        waves = planner.plan_waves()
        await self.executor.execute_plan(waves)
        return _build_execution_report(self.executor, waves, execution_uuid=getattr(self.executor, 'logger', StructuredLogger()).execution_uuid)


class SequentialStrategy(ExecutionStrategy):
    def __init__(self, logger: Optional[StructuredLogger] = None, execution_uuid: Optional[str] = None):
        self.logger = logger or StructuredLogger(execution_uuid=execution_uuid)

    async def execute(self, tasks: List[AtlasTask]) -> Dict[str, Any]:
        results: Dict[str, AtlasTask] = {}
        for task in tasks:
            args = shlex.split(task.command)
            try:
                process = await asyncio.create_subprocess_exec(
                    *args,
                    cwd=task.working_dir,
                    env={**task.env, "ATLAS_TASK_ID": task.id, "ATLAS_WAVE": "0"},
                    stdout=asyncio.subprocess.PIPE,
                    stderr=asyncio.subprocess.PIPE,
                )
                stdout, stderr = await asyncio.wait_for(process.communicate(), timeout=task.timeout)
                task.exit_code = process.returncode or 0
                task.output = stdout.decode() + stderr.decode()
                task.status = TaskStatus.COMPLETED if task.exit_code == 0 else TaskStatus.FAILED
                if task.status == TaskStatus.FAILED:
                    task.error = f"Exit code {task.exit_code}: {task.output[:500]}"
            except asyncio.TimeoutError:
                process.kill()
                await process.wait()
                task.status = TaskStatus.FAILED
                task.error = f"Timeout after {task.timeout}s"
                task.exit_code = -1
            except Exception as e:
                task.status = TaskStatus.FAILED
                task.error = str(e)
                task.exit_code = -1
            task.started_at = time.time()
            task.completed_at = time.time()
            results[task.id] = task
            self.logger.info("task.finished", task_id=task.id, status=task.status.value)
        return {
            "summary": {
                "total_tasks": len(results),
                "completed": sum(1 for t in results.values() if t.status == TaskStatus.COMPLETED),
                "failed": sum(1 for t in results.values() if t.status == TaskStatus.FAILED),
                "skipped": 0,
                "success_rate": sum(1 for t in results.values() if t.status == TaskStatus.COMPLETED) / len(results) if results else 0,
                "total_time_seconds": max((t.completed_at or 0) for t in results.values()) - min((t.started_at or 0) for t in results.values()) if results else 0,
                "waves_executed": 1,
            },
            "tasks": {tid: _task_to_dict(task) for tid, task in results.items()},
            "waves": [{"wave": 0, "tasks": list(results.keys()), "results": {tid: _task_to_dict(task) for tid, task in results.items()}}],
            "execution_uuid": self.logger.execution_uuid,
        }


